const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(`${runtime}/display`, 'utf8').trim();

(async () => {
  const browser = await chromium.launch(config.browser.launchOptions);
  const errors = [];
  try {
    const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
    page.on('pageerror', e => errors.push(e.message));
    await page.goto('http://localhost:3000/', { waitUntil: 'load' });
    if (!(await page.locator('#overlay').evaluate(el => el.classList.contains('visible')))) throw Error('Start overlay is not visible initially');
    await page.locator('#startButton').click();
    if (await page.locator('#overlay').evaluate(el => el.classList.contains('visible'))) throw Error('Start button did not dismiss overlay');

    const startX = await page.evaluate(() => state.player.x);
    await page.keyboard.down('ArrowLeft');
    await page.waitForTimeout(220);
    await page.keyboard.up('ArrowLeft');
    const movedX = await page.evaluate(() => state.player.x);
    if (!(movedX < startX - 20)) throw Error(`Movement did not work (${startX} -> ${movedX})`);

    await page.keyboard.down('Space');
    await page.waitForTimeout(100);
    await page.keyboard.up('Space');
    const bulletCount = await page.evaluate(() => state.bullets.length);
    if (!bulletCount) throw Error('Space did not fire a player bullet');

    await page.evaluate(() => {
      state.enemies = [{ x: state.player.x, y: state.player.y - 115, size: 20, speedX: 0, speedY: 0, hp: 1, cooldown: 99, drift: 0 }];
      state.bullets = [];
      state.player.cooldown = 0;
    });
    await page.keyboard.down('Space');
    await page.waitForTimeout(180);
    await page.keyboard.up('Space');
    await page.waitForTimeout(550);
    const score = await page.locator('#score').innerText();
    if (score !== '100') throw Error(`Expected collision to award 100 points, got ${score}`);

    await page.evaluate(() => {
      state.player.lives = 1;
      state.player.invulnerable = 0;
      state.enemyBullets = [{ x: state.player.x, y: state.player.y, radius: 4, speed: 0, dx: 0, dy: 0, color: '#fff' }];
    });
    await page.waitForTimeout(80);
    if (!(await page.locator('#overlay').evaluate(el => el.classList.contains('visible')))) throw Error('Lethal collision did not show game-over overlay');
    if (!(await page.locator('.panel h1').innerText()).includes('terminado')) throw Error('Game-over title is missing');
    await page.keyboard.press('Enter');
    if (await page.locator('#overlay').evaluate(el => el.classList.contains('visible'))) throw Error('Enter did not restart the game');
    if (await page.locator('#score').innerText() !== '0' || await page.locator('#lives').innerText() !== '5') throw Error('Restart did not reset HUD');
    console.log('Desktop: start, movement, shooting, hit/score, game over, and Enter restart passed.');

    const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
    mobile.on('pageerror', e => errors.push(e.message));
    await mobile.goto('http://localhost:3000/', { waitUntil: 'load' });
    const controlsVisible = await mobile.locator('#touchControls').evaluate(el => getComputedStyle(el).display !== 'none');
    if (!controlsVisible) throw Error('Touch controls are hidden on mobile');
    await mobile.locator('#startButton').tap();
    const mobileX = await mobile.evaluate(() => state.player.x);
    const left = mobile.locator('[data-control="left"]');
    await left.dispatchEvent('pointerdown', { pointerType: 'touch', isPrimary: true, pointerId: 1, button: 0 });
    await mobile.waitForTimeout(160);
    await left.dispatchEvent('pointerup', { pointerType: 'touch', isPrimary: true, pointerId: 1, button: 0 });
    const movedMobileX = await mobile.evaluate(() => state.player.x);
    if (!(movedMobileX < mobileX - 10)) throw Error(`Touch movement failed (${mobileX} -> ${movedMobileX})`);
    const fire = mobile.locator('[data-control="shoot"]');
    await fire.dispatchEvent('pointerdown', { pointerType: 'touch', isPrimary: true, pointerId: 2, button: 0 });
    const touchBulletCount = await mobile.evaluate(() => state.bullets.length);
    if (!touchBulletCount) throw Error('Touch fire control did not shoot');
    console.log('Mobile: touch controls visible, movement and firing passed.');
    if (errors.length) throw Error(`Browser errors: ${errors.join('; ')}`);
    console.log('No uncaught browser errors.');
  } finally {
    await browser.close();
  }
})().catch(error => { console.error(error); process.exitCode = 1; });

